package com.bookstore.user.service;
import com.bookstore.config.JwtService; import com.bookstore.user.dto.*; import com.bookstore.user.entity.User; import com.bookstore.user.repository.UserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public AuthResponse register(RegisterRequest r){if(users.existsByUsernameIgnoreCase(r.username()))throw new IllegalArgumentException("Tên đăng nhập đã tồn tại");if(users.existsByEmailIgnoreCase(r.email()))throw new IllegalArgumentException("Email đã tồn tại");var u=new User();u.setUsername(r.username());u.setPassword(encoder.encode(r.password()));u.setFullName(r.fullName());u.setEmail(r.email());u.setPhone(r.phone());users.save(u);return new AuthResponse(jwt.create(u.getUsername(),u.getRole()),u.getUsername(),u.getRole());} public AuthResponse login(AuthRequest r){var u=users.findByUsername(r.username()).orElseThrow();if(!encoder.matches(r.password(),u.getPassword()))throw new IllegalArgumentException("Invalid credentials");return new AuthResponse(jwt.create(u.getUsername(),u.getRole()),u.getUsername(),u.getRole());} }

